/**
 * @file API Client React package entry point — re-exports all generated hooks, types, and utilities.
 *
 * This package provides a React Query (TanStack Query) based API client with
 * auto-generated hooks for every endpoint in the OpenAPI spec. It wraps a
 * configurable `customFetch` implementation that handles auth tokens, base URLs,
 * and error normalization.
 *
 * ## What is exported?
 * - `generated/api` — React Query hooks (`useHealthCheck`, etc.) and raw fetch functions
 * - `generated/api.schemas` — TypeScript types for request/response payloads
 * - `setBaseUrl` — Configure a base URL for all API calls (useful for mobile/Expo)
 * - `setAuthTokenGetter` — Register a function that supplies bearer tokens for authenticated calls
 *
 * ## Code Generation
 * The hooks and types are generated by Orval (see `shared/api-spec/orval.config.ts`).
 * Do NOT edit the `generated/` directory manually — update `openapi.yaml` and regenerate.
 *
 * ## Usage
 * ```ts
 * import { useHealthCheck, setBaseUrl, setAuthTokenGetter } from "@repo/api-client-react";
 *
 * // Configure once at app startup
 * setBaseUrl("https://api.example.com");
 * setAuthTokenGetter(() => localStorage.getItem("token"));
 *
 * // Use hooks in components
 * function MyComponent() {
 *   const { data, isLoading } = useHealthCheck();
 *   if (isLoading) return <Spinner />;
 *   return <div>Server status: {data?.status}</div>;
 * }
 * ```
 */
export * from "./generated/api";
export * from "./generated/api.schemas";
export { setBaseUrl, setAuthTokenGetter } from "./custom-fetch";
export type { AuthTokenGetter } from "./custom-fetch";
